package transcript

import (
	"encoding/json"
	"strings"
)

// EventKind distinguishes what an Event carries.
type EventKind int

const (
	// EventText is a markdown reply from the assistant.
	EventText EventKind = iota + 1
	// EventTool is a one-line summary of a tool call ("Bash", "git status").
	EventTool
	// EventNotice is a status line generated by the bridge itself.
	EventNotice
)

// Event is one displayable item from the transcript.
type Event struct {
	Kind   EventKind
	Text   string // markdown (EventText) or tool name (EventTool)
	Detail string // EventTool: the most telling argument, single line
}

const maxToolDetail = 160

type entry struct {
	Type        string `json:"type"`
	IsSidechain bool   `json:"isSidechain"`
	Message     struct {
		Content json.RawMessage `json:"content"`
	} `json:"message"`
}

type contentBlock struct {
	Type  string         `json:"type"`
	Text  string         `json:"text"`
	Name  string         `json:"name"`
	Input map[string]any `json:"input"`
}

// ParseLine extracts events from one transcript line. Only main-thread
// assistant output is reported: user turns are already visible in Slack, and
// thinking, tool results and bookkeeping entries are noise on a phone.
func ParseLine(line []byte) []Event {
	var e entry
	if err := json.Unmarshal(line, &e); err != nil || e.Type != "assistant" || e.IsSidechain {
		return nil
	}
	var blocks []contentBlock
	if err := json.Unmarshal(e.Message.Content, &blocks); err != nil {
		return nil
	}

	var events []Event
	for _, b := range blocks {
		switch b.Type {
		case "text":
			if text := strings.TrimSpace(b.Text); text != "" {
				events = append(events, Event{Kind: EventText, Text: text})
			}
		case "tool_use":
			events = append(events, Event{Kind: EventTool, Text: b.Name, Detail: toolDetail(b.Input)})
		}
	}
	return events
}

// toolDetail picks the argument that best explains a tool call.
func toolDetail(input map[string]any) string {
	for _, key := range []string{"command", "file_path", "path", "pattern", "url", "query", "description", "skill", "prompt"} {
		if v, ok := input[key].(string); ok && strings.TrimSpace(v) != "" {
			v, _, _ = strings.Cut(strings.TrimSpace(v), "\n")
			if r := []rune(v); len(r) > maxToolDetail {
				v = string(r[:maxToolDetail]) + "…"
			}
			return v
		}
	}
	return ""
}
